outputs.fact:openQuestions:
[
  {
    "id": "Q1",
    "question": "step.docs.check's findings today are { rule, item, message, fix, severity } with no line number, but the brief's --json is { pass, findings: [{ path, line, rule, message }] } and AC-3 wants the link's line. How should the CLI and the block share findings?",
    "surfaces": [
      "S6",
      "S7"
    ],
    "dimension": "output contract",
    "impact": 3,
    "blocks": [
      "AC-3",
      "AC-5",
      "AC-8"
    ],
    "options": [
      {
        "id": "Q1.a",
        "answer": "One finding builder for both: the block's findings gain a line (the link's 1-based line for DOCS-LINK-001, the unclosed fence's line for DOCS-MD-001, null otherwise). The CLI prints path (from item), line, rule and message, and the block keeps writing item, fix and severity as it does now.",
        "rationale": "Keeps AC-8's parity real: both get findings from the same code, and the line comes from the same place.",
        "cites": [
          "R1",
          "L-product-1"
        ],
        "recommended": true,
        "yields": "AC-3 and AC-5 name line's source; AC-8 compares rule, path and line."
      },
      {
        "id": "Q1.b",
        "answer": "Leave the block unchanged. The CLI works out line numbers itself, only for its own output.",
        "rationale": "Leaves the shipped block alone, but the line logic then lives in two places and AC-8 can compare only rule and path.",
        "cites": [
          "R1",
          "L-product-1"
        ]
      },
      {
        "id": "Q1.c",
        "answer": "The CLI prints the block's findings unchanged (rule, item, message, fix, severity) and drops line from the --json contract.",
        "rationale": "Simplest parity, but it changes the brief's stated --json shape and AC-3's line requirement.",
        "cites": [
          "R1"
        ]
      }
    ],
    "recommended": "Q1.a"
  },
  {
    "id": "Q2",
    "question": "The block reads fact:docsScope (base, globs, candidates) and fact:workspace (the docs worktree path), and step.docs.update runs the CLI on $AW_SINDRI_RUN_DIR. Which files must <dir> hold, and what happens when one is missing or malformed?",
    "surfaces": [
      "S6"
    ],
    "dimension": "input",
    "impact": 3,
    "blocks": [
      "AC-1",
      "AC-6",
      "AC-7"
    ],
    "options": [
      {
        "id": "Q2.a",
        "answer": "<dir> holds one file per fact, named after the fact: docsScope (JSON) and workspace (a path). If either is missing or unreadable, or docsScope has no base, the CLI exits 2 with the same message the block fails with. Nothing is reported as a finding.",
        "rationale": "Matches the run-folder convention and the block's own failure for missing input; exit 1 stays for findings about the docs.",
        "cites": [
          "R1",
          "L-product-1"
        ],
        "recommended": true,
        "yields": "AC-6 gains: a missing or malformed docsScope or workspace exits 2."
      },
      {
        "id": "Q2.b",
        "answer": "Same files, but a missing or malformed fact is reported as a finding and the CLI exits 1.",
        "rationale": "The update agent sees one findings list, but exit 1 would then mix 'your docs are wrong' with 'the check couldn't run'.",
        "cites": [
          "R1",
          "L-product-1"
        ]
      },
      {
        "id": "Q2.c",
        "answer": "<dir> is the docs worktree itself. The CLI checks its uncommitted and committed changes against origin's default branch, using the profile's doc globs, with no fact files.",
        "rationale": "Easier to run by hand, but it stops being step.docs.check's input and drifts from the block.",
        "cites": [
          "R1"
        ]
      }
    ],
    "recommended": "Q2.a"
  },
  {
    "id": "Q3",
    "question": "The block also fails a docs worktree with no change (DOCS-CHANGE-001), which the brief doesn't list. Does the CLI apply that rule too?",
    "surfaces": [
      "S6"
    ],
    "dimension": "rule set",
    "impact": 2,
    "blocks": [
      "AC-1",
      "AC-8"
    ],
    "options": [
      {
        "id": "Q3.a",
        "answer": "Yes. The CLI applies every rule the block does, DOCS-CHANGE-001 included, so an empty change exits 1 with that finding.",
        "rationale": "AC-8 requires the same pass/fail and the same findings, so leaving a rule out would break parity.",
        "cites": [
          "R1",
          "L-product-1"
        ],
        "recommended": true,
        "yields": "AC-1 reads 'at least one changed path' and a new AC covers DOCS-CHANGE-001."
      },
      {
        "id": "Q3.b",
        "answer": "No. With no change the CLI passes (exit 0), because nothing is wrong with the docs. The block keeps DOCS-CHANGE-001 for itself.",
        "rationale": "Friendlier for a hand run before editing, but the CLI and block then disagree on an empty worktree.",
        "cites": [
          "R1"
        ]
      }
    ],
    "recommended": "Q3.a"
  },
  {
    "id": "Q4",
    "question": "'Every markdown file parses' is, in the block today, DOCS-MD-001: every code fence it opens is closed. Is that the whole parse rule for this verb?",
    "surfaces": [
      "S6"
    ],
    "dimension": "rule definition",
    "impact": 2,
    "blocks": [
      "AC-4"
    ],
    "options": [
      {
        "id": "Q4.a",
        "answer": "Yes. 'Parses' means DOCS-MD-001 as the block has it (fences balanced), and AC-4 tests an unclosed fence.",
        "rationale": "Keeps the CLI and the block on one rule with no new dependency. A stricter parser is a separate change to both.",
        "cites": [
          "R1",
          "L-product-1"
        ],
        "recommended": true,
        "yields": "AC-4 names the unclosed-fence case."
      },
      {
        "id": "Q4.b",
        "answer": "No. Both the block and the CLI gain stricter checks (unclosed fences, broken tables, unterminated HTML blocks) through a markdown parser package.",
        "rationale": "Catches more, but needs a new package (Central Package Management, locked restore) and changes the shipped block's behaviour.",
        "cites": [
          "R1",
          "L-product-1"
        ]
      }
    ],
    "recommended": "Q4.a"
  }
]

